class MeanScaler:
    def fit(self, X):
        self.mean_ = [sum(c) / len(c) for c in zip(*X)]
        return self
    def transform(self, X):
        return [[v - m for v, m in zip(r, self.mean_)] for r in X]

train = [[10, 1], [20, 3]]
test = [[40, 2]]
scaler = MeanScaler().fit(train)
print(scaler.mean_, scaler.transform(test))

